import{c as a,Q as e,j as r,m as o}from"./chunks/framework.BPKcPtvA.js";const d=JSON.parse('{"title":"制作人直播说了什么？启燃测试后RO3还能救吗","description":"启燃测试期间制作人YU连续开直播听意见，玩家反馈集中在宠物、精炼、疲劳值。巴哈上有人喊凉有人喊救，真实情况怎么样？","frontmatter":{"title":"制作人直播说了什么？启燃测试后RO3还能救吗","date":"2026-07-02T00:00:00.000Z","description":"启燃测试期间制作人YU连续开直播听意见，玩家反馈集中在宠物、精炼、疲劳值。巴哈上有人喊凉有人喊救，真实情况怎么样？"},"headers":[],"relativePath":"news/producer-livestream-feedback.md","filePath":"news/producer-livestream-feedback.md","lastUpdated":1783172399000}'),p={name:"news/producer-livestream-feedback.md"};function l(n,t,i,s,u,h){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="制作人直播说了什么-启燃测试后ro3还能救吗" tabindex="-1">制作人直播说了什么？启燃测试后RO3还能救吗 <a class="header-anchor" href="#制作人直播说了什么-启燃测试后ro3还能救吗" aria-label="Permalink to &quot;制作人直播说了什么？启燃测试后RO3还能救吗&quot;">​</a></h1><blockquote><p>2026-07-02</p></blockquote><p>启燃测试这七天，除了游戏本身，最让人关注的就是制作人YU的直播。连续几天晚上开直播跟玩家聊天、回答问题，这在RO系列的历史上算比较少见的。</p><p>巴哈上有好几个帖子专门讨论直播内容，有人觉得&quot;制作方还是有救的&quot;，也有人觉得&quot;说了等于没说&quot;。我把直播的关键信息整理了一下。</p><h2 id="制作人到底说了什么" tabindex="-1">制作人到底说了什么 <a class="header-anchor" href="#制作人到底说了什么" aria-label="Permalink to &quot;制作人到底说了什么&quot;">​</a></h2><p>根据巴哈上看了直播的玩家总结，YU主要回应了这几个问题：</p><p><strong>关于宠物系统</strong></p><p>玩家问最多的就是抽卡宠物。YU的回应大概是：宠物系统会调整，但现在测试的版本不是最终版本，具体怎么改还在讨论中。他提到会参考其他游戏的做法，但没有给出具体方案。</p><p>这个回应说实话有点模糊。巴哈上有人解读为&quot;可能砍掉抽卡&quot;，也有人解读为&quot;只是微调&quot;。</p><p><strong>关于疲劳值</strong></p><p>YU解释了疲劳值的设计初衷——是为了防止外挂和工作室刷资源，保护普通玩家的体验。但玩家并不买账。巴哈上有个帖子说得很直接：&quot;你防外挂用疲劳值，那正常玩家凭什么被连坐？&quot;</p><p><strong>关于商业化</strong></p><p>有人在直播里问能不能学王者荣耀那样只卖外观。YU说会参考，但也暗示了RO3的商业化模式已经定型了，大改几乎不可能。不过&quot;会在不影响核心体验的前提下调整&quot;。</p><p>这个&quot;不影响核心体验&quot;怎么定义，就看官方自己的标准了。</p><h2 id="直播的态度" tabindex="-1">直播的态度 <a class="header-anchor" href="#直播的态度" aria-label="Permalink to &quot;直播的态度&quot;">​</a></h2><p>说实话，YU的态度是不错的。直播不是那种念稿式的官方回应，是真的在聊天。有人喷他他也接，有人提建议他也会说&quot;这个可以讨论&quot;。</p><p>巴哈上有个帖子叫&quot;自己的RO3只能自己救——问卷一定要填&quot;，作者说&quot;跟完制作人直播，觉得开发方还是有救有料的&quot;。他的理由是：制作人愿意直播听骂声，说明至少不是完全无视玩家。</p><p>但也有帖子反驳：&quot;态度好有什么用？改不改才是关键。RO系列的态度一直都不错，结果每次都是那样。&quot;</p><h2 id="玩家问卷" tabindex="-1">玩家问卷 <a class="header-anchor" href="#玩家问卷" aria-label="Permalink to &quot;玩家问卷&quot;">​</a></h2><p>直播里提到问卷会开放给玩家填写。巴哈上有人发帖说问卷一开始是开放的，后来因为绑定了玩家ID又关了。这个细节不重要，重要的是问卷的反馈能不能真的影响最终版本。</p><p>RO系列从RO1到现在出了无数个手游，每次测试都有问卷，每次都说&quot;根据反馈调整&quot;，但最终上线的时候改动都微乎其微。玩家的不信任是有历史原因的。</p><h2 id="启燃测试的意义" tabindex="-1">启燃测试的意义 <a class="header-anchor" href="#启燃测试的意义" aria-label="Permalink to &quot;启燃测试的意义&quot;">​</a></h2><p>从官方角度来说，启燃测试是技术验证——测服务器压力、测系统稳定性、测跨平台互通。这些技术层面的东西，从玩家反馈来看问题不大，没人抱怨服务器崩溃或者卡顿。</p><p>但问题在于，玩家不关心你技术验证了什么。玩家关心的是：这游戏值不值得玩、值不值得花钱。</p><p>从巴哈的反应来看，大部分玩家的态度是**&quot;观望&quot;**——不是直接pass，但也没到推荐的程度。有人说了句很精辟的话：&quot;RO3就像一盘菜，食材都不错，但盐放太多了。&quot;</p><h2 id="ro3还有没有机会" tabindex="-1">RO3还有没有机会 <a class="header-anchor" href="#ro3还有没有机会" aria-label="Permalink to &quot;RO3还有没有机会&quot;">​</a></h2><p>从时间线来看，启燃测试7月2号结束，全球公测预计2026年下半年。留给我们的时间不多了。</p><p>好消息是：测试反馈确实能影响最终版本。坏消息是：大改几乎不可能，最多是微调。</p><p>巴哈上有个帖子讨论&quot;如何让一般玩家不讨厌课长制游戏&quot;，提了一个建议——课长买的基础材料，普通玩家打怪也能掉。这样课长花的是时间，普通玩家花的也是时间，只是花钱买时间的人多了一种选择。这个思路其实挺好的，但能不能实现就不知道了。</p><h2 id="还值得关注的" tabindex="-1">还值得关注的 <a class="header-anchor" href="#还值得关注的" aria-label="Permalink to &quot;还值得关注的&quot;">​</a></h2><p>有几个事情值得后续关注：</p><ol><li><p><strong>官方的测试报告</strong>——启燃测试结束后，官方应该会出一份总结，说明收到了什么反馈、会做什么调整。这个才是最核心的信息。</p></li><li><p><strong>正式上线时间</strong>——如果测试反馈太差，上线时间可能会推迟。这是好事，说明他们真的在改。</p></li><li><p><strong>国服进度</strong>——国服要2027年第一季度，比台服晚大半年。如果台服上线后口碑不好，国服能不能顺利上都是问题。</p></li></ol><p>我个人的看法是：RO3还有机会，但窗口期很短。如果正式上线的时候宠物系统还是抽卡制、精炼还是要氪金，那基本就凉了。反过来如果能改成月卡+外观收费，还是能打的。</p><p>就看开发团队愿不愿意壮士断腕了。</p><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li><a href="https://forum.gamer.com.tw/B.php?bsn=81475" target="_blank" rel="noreferrer">巴哈姆特：RO3 哈啦板</a></li><li><a href="https://forum.gamer.com.tw/B.php?bsn=81475" target="_blank" rel="noreferrer">巴哈姆特：制作人YU晚间直播讨论串</a></li><li><a href="https://forum.gamer.com.tw/B.php?bsn=81475" target="_blank" rel="noreferrer">巴哈姆特：自己的RO3只能自己救&gt;&gt;问卷一定要填</a></li><li><a href="https://forum.gamer.com.tw/B.php?bsn=81475" target="_blank" rel="noreferrer">巴哈姆特：理性讨论这游戏有没有前途</a></li></ul>',36)])])}const c=a(p,[["render",l]]);export{d as __pageData,c as default};
